INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Analyse > Problemanalyse
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Problemanalyse immer erforderlich, bevor ein IT-Problem behoben werden kann?', 2, '[{"text": "Nein", "correct": true, "because": "Manchmal reicht Erfahrung, aber Analyse ist optimal"}, {"text": "Ja", "correct": false, "because": "Analyse ist hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Problemanalyse ohne Zugriff auf Systemprotokolle effektiv durchgeführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Methoden wie Beobachtung sind möglich"}, {"text": "Nein", "correct": false, "because": "Protokolle helfen, sind aber nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Probleme während der Analyse vollständig verstanden werden, um eine Lösung zu finden?', 2, '[{"text": "Nein", "correct": true, "because": "Teilverständnis kann ausreichen"}, {"text": "Ja", "correct": false, "because": "Vollständigkeit ist ideal, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Probleme durch eine fehlerhafte Analyse verschlimmert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Falsche Annahmen führen zu schlechten Lösungen"}, {"text": "Nein", "correct": false, "because": "Fehlerhafte Analyse hat oft Konsequenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Problemanalyse unabhängig von der Komplexität des IT-Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität beeinflusst Analyseaufwand"}, {"text": "Ja", "correct": false, "because": "Systemeigenschaften sind relevant"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird häufig für die systematische Problemanalyse in IT-Systemen verwendet?', 3, '[{"text": "Fehlerbaumanalyse", "correct": true, "because": "Identifiziert Ursachen hierarchisch"}, {"text": "Zufällige Vermutung", "correct": false, "because": "Unstrukturiert"}, {"text": "Farbanalyse", "correct": false, "because": "Irrelevant für IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Problemanalyse typischerweise der erste?', 2, '[{"text": "Problemidentifikation", "correct": true, "because": "Definiert das zu lösende Problem"}, {"text": "Lösungsfindung", "correct": false, "because": "Folgt der Analyse"}, {"text": "Dokumentation", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Problemanalyse?', 2, '[{"text": "Ermittlung der Ursache", "correct": true, "because": "Grundlage für Lösung"}, {"text": "Erhöhung der Systemkosten", "correct": false, "because": "Nicht gewünscht"}, {"text": "Vermeidung von Dokumentation", "correct": false, "because": "Gegenteil ist sinnvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann bei der Problemanalyse durch unzureichende Daten entstehen?', 3, '[{"text": "Falsche Ursachenannahme", "correct": true, "because": "Mangelnde Daten führen zu Fehlern"}, {"text": "Schnellere Lösung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Problembehebung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft oft bei der Problemanalyse durch Protokollierung?', 2, '[{"text": "Log-Analyzer", "correct": true, "because": "Untersucht Systemprotokolle"}, {"text": "Texteditor", "correct": false, "because": "Nur für manuelle Bearbeitung"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Problemanalyse in IT-Systemen?', 4, '[{"text": "Datensammlung", "correct": true, "because": "Basis für Analyse"}, {"text": "Hypothesenbildung", "correct": true, "because": "Vermutet Ursachen"}, {"text": "Testen von Annahmen", "correct": true, "because": "Überprüft Hypothesen"}, {"text": "Farbauswahl der Berichte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quellen können für die Problemanalyse genutzt werden?', 3, '[{"text": "Systemprotokolle", "correct": true, "because": "Zeigen Ereignisse"}, {"text": "Benutzerberichte", "correct": true, "because": "Beschreiben Symptome"}, {"text": "Monitoring-Daten", "correct": true, "because": "Liefern Leistungsdaten"}, {"text": "Marketingmaterial", "correct": false, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Problemanalyse erschweren?', 4, '[{"text": "Unvollständige Daten", "correct": true, "because": "Fehlende Informationen"}, {"text": "Komplexe Systeme", "correct": true, "because": "Mehr Ursachen möglich"}, {"text": "Mangelnde Fachkenntnisse", "correct": true, "because": "Erschwert Verständnis"}, {"text": "Schnelle Systemleistung", "correct": false, "because": "Kein Hindernis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gründliche Problemanalyse?', 3, '[{"text": "Genaue Ursachenfindung", "correct": true, "because": "Ziel der Analyse"}, {"text": "Schnellere Problemlösung", "correct": true, "because": "Richtige Ansätze"}, {"text": "Vermeidung von Folgefehlern", "correct": true, "because": "Ursache wird beseitigt"}, {"text": "Geringere Benutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken können bei der Problemanalyse eingesetzt werden?', 3, '[{"text": "Wurzelursachenanalyse", "correct": true, "because": "Findet Grundproblem"}, {"text": "5-Why-Methode", "correct": true, "because": "Fragt nach Ursachen"}, {"text": "Ishikawa-Diagramm", "correct": true, "because": "Visualisiert Zusammenhänge"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unstrukturiert"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Problemanalyse kann mehrere mögliche Ursachen identifizieren. b) Die Analyse ist immer in wenigen Minuten abgeschlossen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Ursachen ja, Zeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemprotokolle sind eine wertvolle Quelle für die Problemanalyse. b) Die Problemanalyse ist unabhängig von der Erfahrung des Analysierenden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Protokolle ja, Erfahrung hilft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine gute Problemanalyse verhindert zukünftige Probleme. b) Die Analyse erfordert keine Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prävention ja, Dokumentation sinnvoll"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Problemanalyse kann durch ungenaue Benutzerangaben erschwert werden. b) Alle Probleme sind mit einer einzigen Analyse lösbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ungenauigkeit ja, Lösung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Problemanalyse kann Teamarbeit erfordern. b) Die Analyse ist immer automatisiert durchführbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teamarbeit ja, Automatisierung begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

